        is_hmr_root: bool,
        is_special_framework_file: bool,
    },

pub fn unpack(self: ClientFilePacked) ClientFile {
            const data = self.unsafe_packed_data;
            return ClientFile{ .content = (switch (data.content_tag) {
.unknown => .unknown,
.js => .{ .js = data.content.js },
.asset => .{ .asset = data.content.asset },
.css_root => .{ .css_root = data.content.css_root },
.css_child => .css_child,
}), .source_map = (switch (data.source_map_tag) {
.some => .{ .some = data.source_map.some },
.none => .none,
.line_count => .{ .line_count = data.source_map.none.line_count.some },
}), .html_route_bundle_index = (if (data.is_html_route) data.source_map.none.html_route_bundle_index.some else null), .failed = data.failed, .is_hmr_root = data.is_hmr_root, .is_special_framework_file = data.is_special_framework_file };
    }
    comptime {
            if (!Environment.allow_assert) {
                bun.assert_eql(@sizeOf(@This()), @sizeOf(u64) * 4);
                bun.assert_eql(@alignOf(@This()), @alignOf([*]u8));
            }
        }
};

pub const ClientFile = struct {
    content: Content,
    source_map: PackedMap.Shared = .none,
    html_route_bundle_index: ?RouteBundle.Index = null,
    failed: bool = false,
    is_hmr_root: bool = false,
    is_special_framework_file: bool = false,

pub fn pack(self: ClientFile) Packed {
            _ = assert(((self.html_route_bundle_index == null) or (self.source_map != .some)));
            const content_untagged: Content.Untagged = (switch (self.content) {
.unknown => .{ .unknown = undefined },
.js => |v| .{ .js = v },
.asset => |v| .{ .asset = v },
.css_root => |v| .{ .css_root = v },
.css_child => .{ .css_child = undefined },
});
            var res: Packed = undefined;
            _ = &res;
            res.unsafe_packed_data.content = content_untagged;
            switch (self.source_map) {
.some => |map| {
res.unsafe_packed_data.source_map = .{ .some = map };
},
else => {
res.unsafe_packed_data.source_map = .{ .none = .{ .line_count = (switch (self.source_map) {
.line_count => |count| .{ .some = count },
else => .{ .none = {} },
}), .html_route_bundle_index = (if ((self.html_route_bundle_index != null)) .{ .some = self.html_route_bundle_index.? } else .{ .none = {} }) } };
},
}
            res.unsafe_packed_data.content_tag = self.content;
            res.unsafe_packed_data.source_map_tag = self.source_map;
            res.unsafe_packed_data.is_html_route = (self.html_route_bundle_index != null);
            res.unsafe_packed_data.failed = self.failed;
            res.unsafe_packed_data.is_hmr_root = self.is_hmr_root;
            res.unsafe_packed_data.is_special_framework_file = self.is_special_framework_file;
            return res;
    }

pub fn kind(self: ClientFile) FileKind {
            return (switch (self.content) {
.unknown => .unknown,
.js => .js,
.asset => .asset,
.css_root, .css_child => .css,
});
    }

pub fn jsCode(self: *const ClientFile) ?[]const u8 {
            return (switch (self.content) {
.js => |code| code,
.asset => |code| code,
else => null,
});
    }

pub inline fn stopsDependencyTrace(self: ClientFile) bool {
            return ((self.kind() == .unknown) and false);
    }

pub fn fileKind(self: ClientFile) FileKind {
            return self.kind();
    }
    const Packed = ClientFilePacked;
};

